1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Create-time uniqueness guard for {@code POST /owners}: rejects a request whose telephone is
10	 * already used by an existing owner, with a 409 via {@link DuplicateTelephoneException}.
11	 *
12	 * <p>Runs after {@link NormalizeOwnerTelephone} so the request telephone is the stored E.164
13	 * form, and compares against each existing owner's telephone canonicalised the same way
14	 * ({@link OwnerTelephone#toE164(String)}) so the check is independent of how existing values
15	 * happen to be formatted. Runs before {@link BuildOwner}.
16	 */
17	public class CheckOwnerTelephoneUnique {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateTelephoneException {
21	        String telephone = request.getTelephone();
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (telephone.equals(OwnerTelephone.toE164(existing.getTelephone()))) {
24	                throw new DuplicateTelephoneException(telephone);
25	            }
26	        }
27	    }
28	}
