1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Create-time household guard for {@code POST /owners}: rejects a request whose last name and
10	 * address both match an existing owner's, with a 409 via {@link DuplicateHouseholdException}.
11	 *
12	 * <p>Last name is compared case-insensitively with collapsed whitespace and address in its
13	 * normalised form (see {@link OwnerAddress#normalize}), so values that differ only in letter
14	 * case, spacing or abbreviation count as the same household. A request may opt out
15	 * of the check by setting {@code sharesHousehold} true (several owners legitimately share one
16	 * household), in which case the duplicate is allowed.
17	 */
18	public class CheckOwnerHouseholdUnique {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws DuplicateHouseholdException {
22	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
23	            return;
24	        }
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (OwnerHousehold.matches(request, existing)) {
27	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
28	            }
29	        }
30	    }
31	}
