1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code namesakeCount}: the number of existing owners that share the new
9	 * owner's {@code firstName} and {@code lastName}, compared case-insensitively.
10	 *
11	 * <p>Runs within the create transaction after {@link BuildOwner} and before {@link SaveOwner},
12	 * so the count reflects the owners that already exist and excludes the owner being created.
13	 */
14	public class AssignNamesakeCount {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String firstName = owner.getFirstName();
18	        String lastName = owner.getLastName();
19	        int count = 0;
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (firstName.equalsIgnoreCase(existing.getFirstName())
22	                    && lastName.equalsIgnoreCase(existing.getLastName())) {
23	                count++;
24	            }
25	        }
26	        owner.setNamesakeCount(count);
27	    }
28	}
