1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>} where
9	 * {@code CITY3} is the upper-cased first three letters of {@code city}, {@code LAST3} the
10	 * upper-cased first three letters of {@code lastName} and {@code NNNN} a per-city 4-digit
11	 * zero-padded sequence equal to one more than the number of owners already in that city
12	 * (e.g. {@code SYD-SMI-0007}).
13	 *
14	 * <p>Runs after {@link BuildOwner} and before {@link SaveOwner}, so the per-city count
15	 * reflects the owners that already exist and excludes the owner being created.
16	 */
17	public class AssignCustomerCode {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String city = owner.getCity();
21	        int sequence = (int) ownerRepository.findAll().stream()
22	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
23	            .count() + 1;
24	        owner.setCustomerCode(String.format("%s-%s-%04d", prefix3(city), prefix3(owner.getLastName()), sequence));
25	    }
26	
27	    /** The upper-cased first three letters of {@code value} (or fewer if it is shorter). */
28	    private static String prefix3(String value) {
29	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
30	    }
31	}
