6	/**
7	 * Assigns the owner's {@code membershipNumber}, formatted {@code <customerCode>-M<YY>}
8	 * where {@code customerCode} is the owner's already-assigned customer code and {@code YY}
9	 * is the last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
10	 *
11	 * <p>Runs after {@link AssignCustomerCode} and {@link BuildOwner} (which assign the
12	 * {@code customerCode} and default the {@code registrationDate}) and before
13	 * {@link SaveOwner}, so both inputs are already set on the owner.
14	 */
15	public class AssignMembershipNumber {
16	
17	    public void service(@Val Owner owner) {
18	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
19	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
20	    }
21	}
