1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Single source of truth for the owner "household" notion used by the {@code POST /owners}
12	 * pipeline: two owners belong to the same household when they share a last name (compared
13	 * case-insensitively with collapsed whitespace) and a normalised address (see
14	 * {@link OwnerAddress#normalize}). Centralised here (rather than inlined in
15	 * {@link CheckOwnerHouseholdUnique} and {@link AssignHousehold}) so the uniqueness guard and
16	 * the id assignment cannot silently disagree about who belongs together.
17	 */
18	final class OwnerHousehold {
19	
20	    private OwnerHousehold() {
21	    }
22	
23	    /** Whether the create request names the same household as an existing owner. */
24	    static boolean matches(OwnerFieldsDto request, Owner existing) {
25	        return normalize(request.getLastName()).equals(normalize(existing.getLastName()))
26	                && OwnerAddress.normalize(request.getAddress())
27	                        .equals(OwnerAddress.normalize(existing.getAddress()));
28	    }
29	
30	    /**
31	     * A stable identifier for the household the request names: the first 8 bytes of
32	     * SHA-256 over the normalised last name and address, upper-cased hex. Deterministic, so
33	     * every member of the same household derives the same id.
34	     */
35	    static String deriveId(OwnerFieldsDto request) {
36	        String key = normalize(request.getLastName()) + "\n" + OwnerAddress.normalize(request.getAddress());
37	        try {
38	            byte[] digest = MessageDigest.getInstance("SHA-256")
39	                    .digest(key.getBytes(StandardCharsets.UTF_8));
40	            StringBuilder sb = new StringBuilder();
41	            for (int i = 0; i < 8; i++) {
42	                sb.append(String.format("%02X", digest[i]));
43	            }
44	            return sb.toString();
45	        }
46	        catch (NoSuchAlgorithmException ex) {
47	            throw new IllegalStateException("SHA-256 not available", ex);
48	        }
49	    }
50	
51	    /** The last-name comparison form: trimmed, internal whitespace collapsed, lower-cased. */
52	    static String normalize(String value) {
53	        if (value == null) {
54	            return "";
55	        }
56	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
57	    }
58	}
