3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Single source of truth for the owner address normalisation rule used across the
8	 * {@code POST /owners} pipeline: an address is canonicalised by trimming, collapsing internal
9	 * whitespace to single spaces, upper-casing, and expanding common abbreviations as whole words
10	 * ({@code ST}→{@code STREET}, {@code RD}→{@code ROAD}, {@code AVE}→{@code AVENUE}). So
11	 * {@code "  12  main  st "} canonicalises to {@code "12 MAIN STREET"} and {@code "7 elm ave"} to
12	 * {@code "7 ELM AVENUE"}.
13	 *
14	 * <p>Centralised here (rather than inlined) so every site agrees on one definition:
15	 * {@link ValidateOwnerFields} stores the canonical value and rejects a value that is blank once
16	 * normalised, while {@link OwnerHousehold} compares the canonical value for duplicate detection
17	 * and the shared household id.
18	 */
19	final class OwnerAddress {
20	
21	    /** Whole-word abbreviations expanded during normalisation. */
22	    private static final Map<String, String> ABBREVIATIONS = Map.of(
23	            "ST", "STREET",
24	            "RD", "ROAD",
25	            "AVE", "AVENUE");
26	
27	    private OwnerAddress() {
28	    }
29	
30	    /**
31	     * The stored/returned/compared form: trimmed, internal whitespace collapsed to single
32	     * spaces, upper-cased, with common abbreviations expanded as whole words. Returns an empty
33	     * string for a null or whitespace-only input.
34	     */
35	    static String normalize(String address) {
36	        if (address == null) {
37	            return "";
38	        }
39	        String trimmed = address.trim();
40	        if (trimmed.isEmpty()) {
41	            return "";
42	        }
43	        String[] tokens = trimmed.toUpperCase(Locale.ROOT).split("\\s+");
44	        StringBuilder sb = new StringBuilder();
45	        for (String token : tokens) {
46	            if (sb.length() > 0) {
47	                sb.append(' ');
48	            }
49	            sb.append(ABBREVIATIONS.getOrDefault(token, token));
50	        }
51	        return sb.toString();
52	    }
53	}
