2	
3	/**
4	 * Single source of truth for the owner telephone normalisation rule used across the
5	 * {@code POST /owners} pipeline: a telephone is canonicalised to E.164 form. Both
6	 * {@link NormalizeOwnerTelephone} (which stores the canonical value and rejects an input that
7	 * cannot form one) and {@link CheckOwnerTelephoneUnique} (which compares stored values) must
8	 * agree on this definition, so it lives here rather than being re-implemented at each site.
9	 *
10	 * <p>The rule: strip spaces, dashes and brackets; keep a leading {@code '+'} and country code
11	 * when present, otherwise assume country code {@code +61} and drop a single leading {@code '0'}
12	 * from the national digits; the result must be a {@code '+'} followed by 8 to 15 digits. So
13	 * {@code "0412 345 678"} canonicalises to {@code "+61412345678"} and {@code "+64 21 123 456"}
14	 * to {@code "+6421123456"}.
15	 */
16	final class OwnerTelephone {
17	
18	    private OwnerTelephone() {
19	    }
20	
21	    /**
22	     * Canonicalise {@code telephone} to E.164 form, or return {@code null} when it cannot form a
23	     * valid E.164 number (null/blank input, a non-digit left after stripping separators, or
24	     * fewer than 8 or more than 15 digits after the {@code '+'}).
25	     */
26	    static String toE164(String telephone) {
27	        if (telephone == null) {
28	            return null;
29	        }
30	        // Strip spaces, dashes and brackets, leaving an optional leading '+' and the digits.
31	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
32	        String digits;
33	        if (cleaned.startsWith("+")) {
34	            // Leading '+' and country code present: keep as-is.
35	            digits = cleaned.substring(1);
36	        } else {
37	            // No country code: assume +61 and drop a single leading '0' from the national digits.
38	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
39	            digits = "61" + national;
40	        }
41	        if (!digits.matches("[0-9]{8,15}")) {
42	            return null;
43	        }
44	        return "+" + digits;
45	    }
46	}
